package reika.electricraft.client.model;

import java.util.List;

import com.mojang.blaze3d.vertex.PoseStack;
import reika.rotarycraft.client.model.TechneModel;
import com.mojang.blaze3d.vertex.VertexConsumer;

import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeDeformation;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.world.level.block.entity.BlockEntity;

@SuppressWarnings("unused")
public class ModelTransformer extends TechneModel {

	protected final ModelPart Shape1;
	protected final ModelPart Shape1a;
	protected final ModelPart Shape2;
	protected final ModelPart Shape2a;
	protected final ModelPart Shape3;
	protected final ModelPart Shape3a;

	public ModelTransformer(ModelPart root) {
		super(root);
		Shape1 = root.getChild("shape1");
		Shape1a = root.getChild("shape1a");
		Shape2 = root.getChild("shape2");
		Shape2a = root.getChild("shape2a");
		Shape3 = root.getChild("shape3");
		Shape3a = root.getChild("shape3a");
	}

	public static LayerDefinition createLayer() {
		MeshDefinition mesh = new MeshDefinition();
		PartDefinition root = mesh.getRoot();
		addParts(root);
		return LayerDefinition.create(mesh, 64, 32);
	}

	protected static void addParts(PartDefinition root) {
		root.addOrReplaceChild("shape1", CubeListBuilder.create().texOffs(0, 0).mirror(false).addBox(0F, 0F, 0F, 4F, 16F, 4F), PartPose.offsetAndRotation(2F, 8F, -2F, 0F, 0F, 0F));
		root.addOrReplaceChild("shape1a", CubeListBuilder.create().texOffs(17, 0).mirror(false).addBox(0F, 0F, 0F, 4F, 16F, 4F), PartPose.offsetAndRotation(-6F, 8F, -2F, 0F, 0F, 0F));
		root.addOrReplaceChild("shape2", CubeListBuilder.create().texOffs(17, 21).mirror(false).addBox(0F, 0F, 0F, 4F, 4F, 4F), PartPose.offsetAndRotation(-2F, 20F, -2F, 0F, 0F, 0F));
		root.addOrReplaceChild("shape2a", CubeListBuilder.create().texOffs(0, 21).mirror(false).addBox(0F, 0F, 0F, 4F, 4F, 4F), PartPose.offsetAndRotation(-2F, 8F, -2F, 0F, 0F, 0F));
		root.addOrReplaceChild("shape3", CubeListBuilder.create().texOffs(34, 8).mirror(false).addBox(0F, 0F, 0F, 6F, 1F, 6F), PartPose.offsetAndRotation(1F, 12.5F, -3F, 0F, 0F, 0F));
		root.addOrReplaceChild("shape3a", CubeListBuilder.create().texOffs(34, 0).mirror(false).addBox(0F, 0F, 0F, 6F, 1F, 6F), PartPose.offsetAndRotation(-7F, 12.5F, -3F, 0F, 0F, 0F));
	}

	@Override
	public void renderAll(PoseStack pose, VertexConsumer vc, int light, int overlay, BlockEntity te, List<?> li, float phi, float theta) {

		Shape1.render(pose, vc, light, overlay);
		Shape1a.render(pose, vc, light, overlay);
		Shape2.render(pose, vc, light, overlay);
		Shape2a.render(pose, vc, light, overlay);

		this.renderCoils(pose, vc, light, overlay, te, li);
	}

	public void renderCoils(PoseStack pose, VertexConsumer vc, int light, int overlay, BlockEntity te, List<?> li) {


		ModelPart[] s = {Shape3, Shape3a};
		for (int c = 0; c <= 1; c++) {
			int n1 = (Integer)li.get(c);
			pose.pushPose();
			int n;
			double ty;
			double dy;
			double sc;
			if (n1 == 1) {
				n = 0;
				dy = sc = ty = 0;
				for (int i = 0; i < 4; i++) {
					pose.pushPose();
					pose.translate(0, i/8D, 0);
					s[c].render(pose, vc, light, overlay);
					pose.popPose();
				}
			}
			else if (n1 < 16) {
				n = 6;
				sc = 0.75;
				dy = 0.25;
				ty = 12;
			}
			else if (n1 < 128) {
				n = 8;
				sc = 0.5;
				dy = 0.75;
				ty = 16;
			}
			else {
				n = 16;
				sc = 0.25;
				dy = 2.25;
				ty = 32;
			}

			for (int i = 0; i < n; i++) {
				pose.pushPose();
				pose.translate(0, i/ty, 0);
				pose.scale(1, (float)sc, 1);
				pose.translate(0, dy, 0);
				s[c].render(pose, vc, light, overlay);
				pose.popPose();
			}

			pose.popPose();
		}
	}

}
